rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isMemberOf(membersMap) {
      return request.auth != null && request.auth.uid in membersMap;
    }
    function hasRole(membersMap, role) {
      return request.auth != null && membersMap[request.auth.uid] == role;
    }
    function hasRequired(fields) {
      return request.resource.data.keys().hasAll(fields);
    }
    function hasOnly(fields) {
      return request.resource.data.keys().hasOnly(fields);
    }
    function validString(field, min, max) {
      return request.resource.data[field] is string && request.resource.data[field].size() >= min && request.resource.data[field].size() <= max;
    }
    function isOneOf(field, values) {
      return request.resource.data[field] in values;
    }
    function fieldUnchanged(field) {
      return resource.data[field] == request.resource.data[field];
    }
    function onlyFieldsChanged(fields) {
      return request.resource.data.diff(resource.data).affectedKeys().hasOnly(fields);
    }
    function getTeam(teamId) {
      return get(/databases/$(database)/documents/teams/$(teamId)).data;
    }
    function isTeamMember(teamId) {
      return request.auth != null && isMemberOf(getTeam(teamId).members);
    }
    function isTeamAdmin(teamId) {
      return request.auth != null && hasRole(getTeam(teamId).members, 'admin');
    }
    match /teams/{teamId} {
      allow read: if isTeamMember(teamId);
      allow write: if request.auth != null;
      match /tasks/{taskId} {
        allow read: if isTeamMember(teamId);
        allow create: if isTeamMember(teamId) && request.resource.data.author == request.auth.uid && hasRequired(['title', 'status', 'author']) && hasOnly(['title', 'status', 'author']) && validString('title', 1, 80) && isOneOf('status', ['open', 'done']);
        allow update: if request.auth != null && resource.data.author == request.auth.uid && fieldUnchanged('author') && onlyFieldsChanged(['title', 'status']) && validString('title', 1, 80) && isOneOf('status', ['open', 'done']);
        allow delete: if isTeamAdmin(teamId);
      }
    }
  }
}

