import { useState, useEffect } from "react";
import { getFirestore, collection, onSnapshot } from "firebase/firestore";

// Declare sandbox as a global provided by the environment
declare const sandbox: any;

// Initialize Firestore authenticated as Alice as requested
const db = getFirestore(sandbox.withAuth({ uid: "alice" }));

interface Item {
  id: string;
  name: string;
  description: string;
  price: number;
}

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const itemsCol = collection(db, "items");
    const unsubscribe = onSnapshot(
      itemsCol,
      (snapshot) => {
        const itemsList: Item[] = [];
        snapshot.forEach((doc) => {
          const data = doc.data();
          itemsList.push({
            id: doc.id,
            name: data.name || "Untitled Item",
            description: data.description || "No description provided.",
            price: typeof data.price === "number" ? data.price : 0,
          });
        });
        setItems(itemsList);
        setLoading(false);
        setError(null);
      },
      (err) => {
        console.error("Error fetching items:", err);
        setError(err.message);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  return (
    <div className="container">
      <header className="header">
        <h1>Catalog Items</h1>
        <div className="badge">Signed in as: <strong>alice</strong></div>
      </header>

      <main className="content">
        {loading && <div className="status">Loading catalog items...</div>}
        {error && <div className="status error">Error: {error}</div>}
        {!loading && !error && items.length === 0 && (
          <div className="status empty">No items found in the catalog.</div>
        )}

        <div className="items-grid">
          {items.map((item) => (
            <div key={item.id} className="item-card">
              <div className="item-info">
                <h3 className="item-name">{item.name}</h3>
                <p className="item-description">{item.description}</p>
              </div>
              <div className="item-price">
                ${item.price.toFixed(2)}
              </div>
            </div>
          ))}
        </div>
      </main>

      <style>{`
        :root {
          --bg-color: #f9fafb;
          --card-bg: #ffffff;
          --text-primary: #111827;
          --text-secondary: #4b5563;
          --primary-color: #2563eb;
          --border-color: #e5e7eb;
        }

        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
          background-color: var(--bg-color);
          color: var(--text-primary);
        }

        .container {
          max-width: 480px;
          margin: 0 auto;
          padding: 16px;
          display: grid;
          gap: 16px;
        }

        .header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          border-bottom: 1px solid var(--border-color);
          padding-bottom: 12px;
        }

        .header h1 {
          font-size: 1.5rem;
          margin: 0;
          font-weight: 700;
        }

        .badge {
          font-size: 0.8rem;
          background-color: #e0f2fe;
          color: #0369a1;
          padding: 4px 8px;
          border-radius: 9999px;
        }

        .content {
          display: grid;
          gap: 12px;
        }

        .status {
          text-align: center;
          padding: 24px;
          color: var(--text-secondary);
          background-color: var(--card-bg);
          border-radius: 8px;
          border: 1px dashed var(--border-color);
        }

        .status.error {
          color: #dc2626;
          background-color: #fef2f2;
          border-color: #fca5a5;
        }

        .items-grid {
          display: grid;
          gap: 12px;
        }

        .item-card {
          background-color: var(--card-bg);
          border: 1px solid var(--border-color);
          border-radius: 12px;
          padding: 16px;
          display: flex;
          justify-content: space-between;
          align-items: center;
          box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
          transition: transform 0.2s, box-shadow 0.2s;
        }

        .item-card:hover {
          transform: translateY(-1px);
          box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
        }

        .item-info {
          display: grid;
          gap: 4px;
          flex: 1;
          padding-right: 12px;
        }

        .item-name {
          margin: 0;
          font-size: 1rem;
          font-weight: 600;
        }

        .item-description {
          margin: 0;
          font-size: 0.85rem;
          color: var(--text-secondary);
          line-height: 1.4;
        }

        .item-price {
          font-size: 1.1rem;
          font-weight: 700;
          color: var(--primary-color);
          white-space: nowrap;
        }
      `}</style>
    </div>
  );
}
